describe('UserGroupMembershipRepository', () => {
  let inner: RepositoryMock;
  let repository: UserGroupMembershipRepository;

  beforeEach(() => {
    // Sin constructor: el RepositoryService interno (y su conector) se sustituye por un doble
    inner = mockRepository('RepositoryService');
    repository = Object.create(UserGroupMembershipRepository.prototype);
    internals(repository).repo = inner;
  });

  it('delegates acl, context and checkAcl', () => {
    expect(repository.acl()).toBe(inner['acl']());
    expect(repository.context()).toBe(inner['context']());
    repository.checkAcl('key-1');
    expect(inner['checkAcl']).toHaveBeenCalledWith('key-1');
    repository.checkAcl();
    expect(inner['checkAcl']).toHaveBeenCalledWith(null);
    expect(repository.generateComb()).toBe('generated-key');
  });

  it('adds with a generated key', () => {
    repository.add({ uid: '' } as any);
    expect(inner['add']).toHaveBeenCalledWith(jasmine.objectContaining({ uid: 'generated-key' }));
  });

  it('updates with its options', () => {
    const item = { uid: 'key-1' } as any;
    repository.update(item, { original: item });
    expect(inner['update']).toHaveBeenCalledWith(item, { original: item });
  });

  it('deletes by key and by selection', () => {
    repository.deleteByKey('key-1');
    expect(inner['deleteByKey']).toHaveBeenCalledWith('key-1');
    expect(repository.canDeleteSelection()).toBeTrue();
    repository.deleteSelection({ uids: ['key-1'] });
    expect(inner['deleteSelection']).toHaveBeenCalledWith({ uids: ['key-1'] });
  });

  it('retrieves and projects one item', () => {
    repository.retrieve('key-1');
    expect(inner['retrieve']).toHaveBeenCalledWith('key-1');
    repository.projection([]);
    expect(inner['projection']).toHaveBeenCalledWith([], undefined);
    repository.resolve('key-1', []);
    expect(inner['resolve']).toHaveBeenCalledWith('key-1', [], undefined);
    repository.resolveAll([], []);
    expect(inner['resolveAll']).toHaveBeenCalledWith([], [], undefined);
  });

  it('lists with the public filter', () => {
    const filter = {
      search: 'text',
      uids: ['key-1'],
      limit: 5,
      user: 'filter-user',
      users: 'filter-users',
      resourceServer: 'filter-resourceServer',
      resourceServers: 'filter-resourceServers',
      oauthClient: 'filter-oauthClient',
      oauthClients: 'filter-oauthClients',
      cursor: 'next-page',
      empty: '',
    } as any;
    const expected = {
      search: 'text',
      uids: ['key-1'],
      limit: 5,
      user: 'filter-user',
      users: 'filter-users',
      resourceServer: 'filter-resourceServer',
      resourceServers: 'filter-resourceServers',
      oauthClient: 'filter-oauthClient',
      oauthClients: 'filter-oauthClients',
      cursor: 'next-page',
    };
    repository.list(filter);
    expect(inner['list']).toHaveBeenCalledWith(expected);
    repository.values(filter);
    expect(inner['values']).toHaveBeenCalledWith(expected);
    repository.projections([]);
    expect(inner['projections']).toHaveBeenCalledWith([], undefined);
  });

  it('drops the empty filter fields', () => {
    repository.list({ search: '', limit: 0 } as any);
    expect(inner['list']).toHaveBeenCalledWith({});
  });

  it('gives its children by user', () => {
    repository.children('user');
    expect(inner['children']).toHaveBeenCalledWith('user', 'users', [], undefined);
  });

  it('gives its children by resourceServer', () => {
    repository.children('resourceServer');
    expect(inner['children']).toHaveBeenCalledWith('resourceServer', 'resourceServers', [], undefined);
  });

  it('gives its children by oauthClient', () => {
    repository.children('oauthClient');
    expect(inner['children']).toHaveBeenCalledWith('oauthClient', 'oauthClients', [], undefined);
  });

  it('displays the item by uid', () => {
    expect(repository.displayProvider().display({ uid: 'shown' } as any)).toBe('shown');
  });

  it('offers a selector over its values', () => {
    const selector = repository.selectorProvider();
    selector.search('text');
    expect(inner['values']).toHaveBeenCalledWith({ search: 'text', limit: 10 });
    expect(selector.display({ uid: 'shown' } as any)).toBe('shown');
    expect(selector.value({ uid: 'key-1' } as any)).toEqual(jasmine.objectContaining({ $ref: 'key-1' }));
    expect(selector.equals({ $ref: 'a' }, { $ref: 'a' })).toBeTrue();
    expect(selector.equals({ $ref: 'a' }, { $ref: 'b' })).toBeFalse();
    selector.select({ $ref: 'key-1' });
    expect(inner['retrieve']).toHaveBeenCalledWith('key-1');
  });

  it('searches the selector with its own filter', () => {
    const selector = repository.selectorProvider(signal({ limit: 3 } as any));
    selector.search('text');
    expect(inner['values']).toHaveBeenCalledWith({ limit: 3, search: 'text' });
    selector.select({ $ref: '' });
    expect(inner['retrieve']).not.toHaveBeenCalled();
    expect(selector.selection()).toBeNull();
  });
});
